// Wallet IDs (audit 98cd2a781, run 66). Every account has a permanent uint32 ID: its position in
// GAME's `wallets` table. Per-player storage maps are
// keyed by that ID and most events carry it instead of an address, so a reader resolves the
// viewer's address to its ID ONCE (Game `walletIdOf`) and IDs back to addresses through the
// table itself. Cache lifetimes follow the account's identity:
//   - ID -> address is permanent for an ordinary account (the table's key lane never changes,
//     liquidation keeps the seller key). A smurf (key lane zero) resolves to its owner's address,
//     its payee; that answer can move when the owner is sold, so it is not cached.
//   - address -> ID is cached only for one block snapshot: liquidation clears the default ID. Zero (not registered yet) is re-read every time: the
//     first paying transaction registers the wallet.
// Protocol IDs 1-3 (VAULT, SDGNRS, GNRUS) are ordinary table rows written by Game's constructor.
// On older deployments (hasWalletIds() false) every helper here is an identity on the address.
import { hasWalletIds } from './schema.js';

const ADDRESS_MASK = (1n << 160n) - 1n;
let idCache = new WeakMap();      // `${game}:${address}` -> id (nonzero only)
const addressCache = new Map(); // `${game}:${id}` -> lowercase address (ordinary accounts only)

// Keyed by chain id too: test fixtures (and a chain switch) reuse contract addresses.
const gameKey = s => `${s.client.chain?.id ?? ''}:${s.client.address('GAME')}`;
const lower = value => String(value ?? '').toLowerCase();
export const isWalletAddress = value => /^0x[0-9a-f]{40}$/i.test(String(value ?? ''));

/** The wallet ID of `address` on the snapshot's deployment; 0 when it has not registered. */
export async function walletIdOf(s, address) {
  if (!hasWalletIds() || !isWalletAddress(address)) return 0;
  const key = lower(address);
  let ids = idCache.get(s);
  if (!ids) { ids = new Map(); idCache.set(s, ids); }
  if (ids.has(key)) return ids.get(key);
  const id = Number(await s.call('GAME', 'walletIdOf', [lower(address)]));
  if (id) { ids.set(key, id); addressCache.set(`${gameKey(s)}:${id}`, lower(address)); }
  return id;
}

/** Raw wallet-table element of `id` (0n for an unallocated ID). */
async function walletElement(s, id) {
  try { return BigInt(await s.field('GAME', 'wallets', id)); }
  catch (error) { if (/out of bounds/i.test(String(error?.message))) return 0n; throw error; }
}

/**
 * The address an ID stands for: an ordinary account's own key, or a smurf's payee (its owner's
 * key, following at most two owner links as Game's _payee does). null for 0 or an unknown ID.
 */
export async function walletAddressOf(s, id) {
  const n = Number(id ?? 0);
  if (!hasWalletIds() || !Number.isSafeInteger(n) || n <= 0) return null;
  const key = `${gameKey(s)}:${n}`;
  if (addressCache.has(key)) return addressCache.get(key);
  let element = await walletElement(s, n);
  let address = element & ADDRESS_MASK;
  if (address !== 0n) {
    const out = '0x' + address.toString(16).padStart(40, '0');
    addressCache.set(key, out);
    return out;
  }
  for (let hop = 0; hop < 2 && address === 0n; hop++) {
    const owner = Number((element >> 160n) & 0xffffffffn);
    if (!owner) return null;
    element = await walletElement(s, owner); address = element & ADDRESS_MASK;
  }
  return address === 0n ? null : '0x' + address.toString(16).padStart(40, '0');
}

/** Resolve many IDs at once (reads coalesce into the snapshot's multicall). Map id -> address|null. */
export async function walletAddresses(s, ids) {
  const unique = [...new Set([...ids].map(Number).filter(n => Number.isSafeInteger(n) && n > 0))];
  const pairs = await Promise.all(unique.map(async id => [id, await walletAddressOf(s, id)]));
  return new Map(pairs);
}

/**
 * The storage/view key for a player on the active deployment: the wallet ID from run 66, the
 * address before. A run-66 reader that gets 0 must treat the wallet as having no state.
 */
export async function playerKey(s, address) {
  return hasWalletIds() ? walletIdOf(s, address) : lower(address);
}

/** Tests: forget every cached resolution. */
export function clearWalletCacheForTests() { idCache = new WeakMap(); addressCache.clear(); }
